                       {"buf.21", "scratch dsa_index_score.hist 131072 0 0"},
                       {"buf.22", "out idx_scores 524288 -1 0"},
                       {"buf.23", "out dsa_index_topk.records.10 9728 -1 0"},
                       {"buf.24", "tensor indices 16384 -1 0"},
                       {"buf.25", "out mla_split 2101248 -1 0"},
                       {"buf.26", "out o_lat 65536 -1 0"},
                       {"buf.27", "tensor w_uv 1048576 -1 0"},
                       {"buf.28", "out v 32768 -1 0"},
                       {"buf.29", "exchange v_fp8 16896 255 0"},
