                       {"buf.32", "exchange o_sent 98304 255 1"},
                       {"buf.33", "out o_sum 98304 255 1"},
                       {"buf.34", "tensor residual 49152 -1 0"},
                       {"buf.35", "tensor attn_out 49152 -1 0"},
                       {"map.0", "wblk8 t:w_qkva 1008 1"},
                       {"map.1", "wblk8 t:w_qkva 1008 2"},
                       {"map.2", "act8 b:1+0 6144 8"},
                       {"map.3", "act8 b:1+196608 6144 8"},
                       {"map.4", "act8kt b:1+0 6144 8 2"},
                       {"map.5", "act8kt b:1+196608 6144 8 2"},
                       {"map.6", "bf16 t:w_kw 256 6144 128"},
                       {"map.7", "bf16 t:w_kw 256 6144 64"},
                       {"map.8", "bf16 t:x 8 6144 8"},
                       {"map.9", "wblk8 t:w_qb 256 1"},
                       {"map.10", "wblk8 t:w_qb 256 2"},
                       {"map.11", "act8 b:6+0 2048 8"},
                       {"map.12", "act8 b:6+196608 2048 8"},
                       {"map.13", "act8kt b:6+0 2048 8 2"},
                       {"map.14", "act8kt b:6+196608 2048 8 2"},
                       {"map.15", "wblk8 t:w_iqb 512 1"},
                       {"map.16", "wblk8 t:w_iqb 512 2"},
                       {"map.17", "wblk8 t:w_o 768 1"},
                       {"map.18", "wblk8 t:w_o 768 2"},
                       {"map.19", "act8 b:29+0 2048 8"},
